{
  "concept": "A vector field grid shows the local magnitude and direction of the electric field at discrete points, but continuous field lines can represent the same directional flow more clearly without visual clutter.",
  "figureType": "diagram",
  "elements": [
    "x-axis labeled 'x (m)' with ticks from -2 to 4",
    "y-axis labeled 'y (m)' with ticks from -2 to 2",
    "invisible positive charge at (0,0) acting as a source",
    "invisible negative charge at (2,0) acting as a sink",
    "grid of dark blue arrows representing the electric field vectors, lengths scaled by magnitude",
    "continuous field lines (in field-line view) running from (0,0) to (2,0)",
    "hover overlay showing enlarged resultant vector, magnitude readout, and two component vectors from the individual charges"
  ],
  "interactions": [
    {
      "id": "representationToggle",
      "type": "toggle",
      "label": "Representation",
      "options": [
        "Vector grid",
        "Field lines"
      ],
      "default": "Vector grid",
      "teaches": "Continuous field lines encode the same directional pattern as the vector grid but remove the visual clutter caused by hundreds of overlapping arrows."
    },
    {
      "id": "localFieldHover",
      "type": "hover",
      "teaches": "The net electric field at any point in space is simply the vector sum of the individual fields produced by the positive and negative charges."
    },
    {
      "id": "gridDensity",
      "type": "slider",
      "label": "Grid density",
      "range": [
        10,
        40,
        5
      ],
      "default": 20,
      "teaches": "The visual density of the arrows is a choice of the plot's sampling rate, not a physical property of the underlying continuous field."
    }
  ],
  "demo_steps": [
    {
      "title": "The Vector Grid",
      "narration": "This plot samples the electric field at a regular grid of points. The arrows point away from the source at the origin and toward the sink at x=2.",
      "state": {
        "representationToggle": "Vector grid",
        "gridDensity": 20
      }
    },
    {
      "title": "Superposition in Action",
      "narration": "Hover over any arrow to see how it is formed. The field at every point is the exact vector sum of a push away from the positive charge and a pull toward the negative charge.",
      "state": {
        "representationToggle": "Vector grid",
        "gridDensity": 20
      }
    },
    {
      "title": "The Clutter Problem",
      "narration": "Increasing the sampling density gives more information but quickly makes the plot unreadable as arrows overlap.",
      "state": {
        "representationToggle": "Vector grid",
        "gridDensity": 40
      }
    },
    {
      "title": "Switching to Field Lines",
      "narration": "By connecting the directions into continuous field lines, we can clearly see the flow from positive to negative charge without the messy grid.",
      "state": {
        "representationToggle": "Field lines",
        "gridDensity": 20
      }
    }
  ],
  "keyInsight": "A grid of vectors accurately depicts local field values via superposition, but continuous field lines are often a better visual tool for understanding the overall shape of the field.",
  "reconstructionNotes": "Create a 2D coordinate space mapping x in [-2.5, 4.5] and y in [-2.5, 2.5]. In 'Vector grid' mode, draw arrows at grid intersections. Arrow direction follows the dipole field formula; length is proportional to the log of the magnitude to keep them visible everywhere without crossing over each other near the charges. In 'Field lines' mode, hide the grid and draw smooth curves that originate at (0,0) and terminate at (2,0) or exit the boundary, adding directional arrowheads along the paths. The hover interaction should display a faint line to each charge source, showing the individual E-field vectors and their parallelogram sum."
}

