  </label>
</div>

<label style="display: block; font-weight: bold; color: #0f172a; margin-top: 10px;">
  Grid density: <output id="densityVal" style="font-weight: normal; color: #334155;">20</output>
  <input id="densityInput" type="range" min="10" max="40" step="5" value="20" style="width: 100%; margin-top: 6px; cursor: pointer;" oninput="document.getElementById('densityVal').value=this.value; updateDensity(+this.value)">
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
setPlotFrame({ xDomain: [-2.2, 4.2], yDomain: [-2.2, 2.2], margin: 60 });

const steps = [
  {
    title: "The Vector Grid",
    narration: "This plot samples the electric field at a regular grid of points. The arrows point away from the source at the origin and toward the sink at x=2.",
    state: { rep: "grid", density: 20 }
  },
  {
    title: "Superposition in Action",
    narration: "Hover over any arrow to see how it is formed. The field at every point is the exact vector sum of a push away from the positive charge and a pull toward the negative charge.",
    state: { rep: "grid", density: 20 }
  },
  {
    title: "The Clutter Problem",
    narration: "Increasing the sampling density gives more information but quickly makes the plot unreadable as arrows overlap.",
    state: { rep: "grid", density: 40 }
  },
  {
    title: "Switching to Field Lines",
    narration: "By connecting the directions into continuous field lines, we can clearly see the flow from positive to negative charge without the messy grid.",
    state: { rep: "lines", density: 20 }
  }
];

let currentStep = 0;
let currentMode = 'grid';
let currentDensity = 20;

const frameGroup = _plotFrame.draw.group();
const axesGroup = _plotFrame.draw.group();
const fieldGroup = _plotFrame.draw.group();
const hoverGroup = _plotFrame.draw.group();

document.addEventListener('fig-resize', renderAll);

function renderAll() {
  frameGroup.clear();
  axesGroup.clear();

  const fw = _plotFrame.width - 2 * _plotFrame.margin;
  const fh = _plotFrame.height - 2 * _plotFrame.margin;

  const frame = frameGroup.rect(fw, fh)
    .move(_plotFrame.margin, _plotFrame.margin)
    .fill('transparent')
    .stroke({ color: '#111', width: 1.2 });

  for (let y = -2; y <= 2; y++) {
    const px = plotX(-2.2);
    const py = plotY(y);
    axesGroup.line(px, py, px + 5, py).stroke({ color: '#111', width: 1.2 });
    axesGroup.text(y.toString())
      .attr({ x: px - 8, y: py })
      .font({ size: 12, family: 'sans-serif', anchor: 'end', 'dominant-baseline': 'central' });
  }

  axesGroup.text('y (m)')
    .attr({ x: plotX(-2.2) - 36, y: plotY(0) })
    .font({ size: 14, family: 'sans-serif', anchor: 'middle', weight: 'bold', 'dominant-baseline': 'central' })
    .attr('transform', `rotate(-90, ${plotX(-2.2) - 36}, ${plotY(0)})`);

  for (let x = -2; x <= 4; x++) {
    const px = plotX(x);
    const py = plotY(-2.2);
    axesGroup.line(px, py, px, py - 5).stroke({ color: '#111', width: 1.2 });
    axesGroup.text(x.toString())
      .attr({ x: px, y: py + 14 })
      .font({ size: 12, family: 'sans-serif', anchor: 'middle', 'dominant-baseline': 'hanging' });
  }

  axesGroup.text('x (m)')
    .attr({ x: plotX(1), y: plotY(-2.2) + 38 })
    .font({ size: 14, family: 'sans-serif', anchor: 'middle', weight: 'bold', 'dominant-baseline': 'hanging' });

  drawContent();

  frame.on('mousemove', handleHover);
  frame.on('mouseleave', () => { 
    hoverGroup.clear(); 
    hideTooltip(); 
  });
}

function getE(x, y) {
  const dx1 = x, dy1 = y;
  const r1_sq = dx1 * dx1 + dy1 * dy1;
  const r1 = Math.sqrt(r1_sq);

  const dx2 = x - 2, dy2 = y;
  const r2_sq = dx2 * dx2 + dy2 * dy2;
  const r2 = Math.sqrt(r2_sq);

  const ex1 = r1 > 0.02 ? dx1 / (r1_sq * r1) : 0;
  const ey1 = r1 > 0.02 ? dy1 / (r1_sq * r1) : 0;

  const ex2 = r2 > 0.02 ? -dx2 / (r2_sq * r2) : 0;
  const ey2 = r2 > 0.02 ? -dy2 / (r2_sq * r2) : 0;

  return { ex1, ey1, ex2, ey2, ex: ex1 + ex2, ey: ey1 + ey2 };
}

function drawContent() {
  fieldGroup.clear();
  hoverGroup.clear();

  if (currentMode === 'grid') {
    const step = 4 / currentDensity;
    for (let x = -2; x <= 4.01; x += step) {
      for (let y = -2; y <= 2.01; y += step) {
        if (Math.hypot(x, y) < 0.1 || Math.hypot(x - 2, y) < 0.1) continue;

        const { ex, ey } = getE(x, y);
        const mag = Math.sqrt(ex * ex + ey * ey);
        if (mag < 1e-4) continue;

        const len = 0.4 * (mag / (mag + 1.2));
        const ux = ex / mag;
        const uy = ey / mag;

        const px1 = plotX(x);
        const py1 = plotY(y);
        const px2 = plotX(x + ux * len);
        const py2 = plotY(y + uy * len);

        fieldGroup.line(px1, py1, px2, py2).stroke({ color: '#1a3b5c', width: 1.2, linecap: 'round' });

        const ang = Math.atan2(py2 - py1, px2 - px1);
        fieldGroup.polygon('0,-2.5 5,0 0,2.5')
          .fill('#1a3b5c')
          .attr('transform', `translate(${px2},${py2}) rotate(${ang * 180 / Math.PI})`);
      }
    }
  } else {
    const numLines = 22;
    const ds = 0.02;

    for (let i = 0; i < numLines; i++) {
      let angle = i * Math.PI * 2 / numLines;
      let x = 0.1 * Math.cos(angle);
      let y = 0.1 * Math.sin(angle);

      let pts = [[x, y]];
      let iters = 0;

      while (iters < 1500) {
        const { ex, ey } = getE(x, y);
        const mag = Math.sqrt(ex * ex + ey * ey);
        if (mag < 1e-5) break;

        x += ds * (ex / mag);
        y += ds * (ey / mag);
        pts.push([x, y]);

        if (Math.hypot(x - 2, y) < 0.1) break;
        if (x < -2.2 || x > 4.2 || y < -2.2 || y > 2.2) break;
        iters++;
      }

      if (pts.length > 1) {
        const pathD = 'M ' + pts.map(p => `${plotX(p[0])},${plotY(p[1])}`).join(' L ');
        fieldGroup.path(pathD).fill('none').stroke({ color: '#1a3b5c', width: 1.5 });

        [0.25, 0.65].forEach(f => {
          const idx = Math.floor(pts.length * f);
          if (idx > 0 && idx < pts.length - 1) {
            const p1 = pts[idx - 1];
            const p2 = pts[idx + 1];
            const ang = Math.atan2(plotY(p2[1]) - plotY(p1[1]), plotX(p2[0]) - plotX(p1[0]));
            const mx = plotX(pts[idx][0]);
            const my = plotY(pts[idx][1]);

            fieldGroup.polygon('0,-4 8,0 0,4')
              .fill('#1a3b5c')
              .attr('transform', `translate(${mx},${my}) rotate(${ang * 180 / Math.PI})`);
          }
        });
      }
    }
  }
}

function handleHover(e) {
  if (currentMode !== 'grid') return;

  const rect = document.getElementById('container').getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  const wx = _plotFrame.xDomain[0] + (mx - _plotFrame.margin) / _plotFrame.sx;
  const wy = _plotFrame.yDomain[0] - (my - (_plotFrame.height - _plotFrame.margin)) / _plotFrame.sy;

  const step = 4 / currentDensity;
  const gx = Math.round(wx / step) * step;
  const gy = Math.round(wy / step) * step;

  if (Math.abs(wx - gx) > step * 0.7 || Math.abs(wy - gy) > step * 0.7) {
    hoverGroup.clear();
    hideTooltip();
    return;
  }

  if (Math.hypot(gx, gy) < 0.1 || Math.hypot(gx - 2, gy) < 0.1) return;
  if (gx < -2 || gx > 4 || gy < -2 || gy > 2) return;

  hoverGroup.clear();

  const { ex1, ey1, ex2, ey2, ex, ey } = getE(gx, gy);
  const mag = Math.sqrt(ex * ex + ey * ey);

  const scale = 0.7 / (mag + 0.5); 
  const dX1 = ex1 * scale, dY1 = ey1 * scale;
  const dX2 = ex2 * scale, dY2 = ey2 * scale;
  const dX = ex * scale, dY = ey * scale;

  const px = plotX(gx), py = plotY(gy);

  hoverGroup.line(plotX(0), plotY(0), px, py).stroke({ color: '#e53935', width: 1.5, dasharray: '3,4', opacity: 0.35 });
  hoverGroup.line(plotX(2), plotY(0), px, py).stroke({ color: '#1e88e5', width: 1.5, dasharray: '3,4', opacity: 0.35 });

  drawVector(hoverGroup, gx, gy, dX1, dY1, '#e53935', 2);
  drawVector(hoverGroup, gx, gy, dX2, dY2, '#1e88e5', 2);

  hoverGroup.line(plotX(gx + dX1), plotY(gy + dY1), plotX(gx + dX), plotY(gy + dY))
    .stroke({ color: '#1e88e5', width: 1.5, dasharray: '4,4', opacity: 0.8 });
  hoverGroup.line(plotX(gx + dX2), plotY(gy + dY2), plotX(gx + dX), plotY(gy + dY))
    .stroke({ color: '#e53935', width: 1.5, dasharray: '4,4', opacity: 0.8 });

  drawVector(hoverGroup, gx, gy, dX, dY, '#111', 3);

  showTooltip(`Net Field |E| = ${mag.toFixed(2)}`, e);
}

function drawVector(g, x, y, dx, dy, color, width) {
  const p1x = plotX(x), p1y = plotY(y);
  const p2x = plotX(x + dx), p2y = plotY(y + dy);

  g.line(p1x, p1y, p2x, p2y).stroke({ color: color, width: width, linecap: 'round' });

  const ang = Math.atan2(p2y - p1y, p2x - p1x);
  g.polygon('0,-4.5 9,0 0,4.5')
    .fill(color)
    .attr('transform', `translate(${p2x},${p2y}) rotate(${ang * 180 / Math.PI})`);
}

window.updateRep = function(rep) {
  currentMode = rep;
  drawContent();
};

window.updateDensity = function(d) {
  currentDensity = d;
  if (currentMode === 'grid') drawContent();
};

window.prevStep = function() {
  if (currentStep > 0) applyStep(currentStep - 1);
};

window.nextStep = function() {
  if (currentStep < steps.length - 1) applyStep(currentStep + 1);
};

function applyStep(idx) {
  currentStep = idx;
  const step = steps[idx];

  document.getElementById('stepLabel').textContent = `Step ${idx + 1} of ${steps.length}`;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('demoNarration').textContent = step.narration;

  const prev = document.getElementById('prevBtn');
  const next = document.getElementById('nextBtn');
  prev.disabled = (idx === 0);
  next.disabled = (idx === steps.length - 1);
  prev.style.opacity = prev.disabled ? '0.4' : '1';
  next.style.opacity = next.disabled ? '0.4' : '1';

  const radios = document.getElementsByName('rep');
  for (let r of radios) {
    if (r.value === step.state.rep) r.checked = true;
  }

  const slider = document.getElementById('densityInput');
  slider.value = step.state.density;
  document.getElementById('densityVal').value = step.state.density;

  currentMode = step.state.rep;
  currentDensity = step.state.density;
  drawContent();
}

renderAll();
applyStep(0);
window.__markRendered();
